#!/usr/bin/env bash
# ═════════════════════════════════════════════════════════════════════════
#  nordic-env-installer.sh — INSTALADOR AUTOCONTENIDO del entorno kali-nordic
#  (bspwm + polybar Nord + picom glass + kitty + rofi + sxhkd + nano VS Code
#   + zsh/powerlevel10k + LightDM greeter Nord + lockscreen/suspend Nord)
#
#  TODO el entorno va embebido en PAYLOAD_B64 (tar.gz + md5 validado).
#  Lo ejecuta TU USUARIO (no root). Pasos:
#    1) VALIDACIONES del sistema (nada se escribe hasta pasarlas)
#    2) descodificación + verificación MD5 del payload embebido
#    3) extracción a ~/.cache/nordic/install-repo
#    4) install.sh (valida e instala paquetes faltantes por apt)
#    5) POST-VALIDACIÓN de ficheros clave + nordic-doctor
#
#  Uso:  bash nordic-env-installer.sh
# ═════════════════════════════════════════════════════════════════════════
set -Eeuo pipefail
export PATH="$PATH:/usr/local/bin"
FAIL=()
step() { printf '  • %s\n' "$*"; }
die() { printf '\n  ✘ %s — nada se ha instalado.\n' "$*"; exit 1; }

echo "  ══ kali-nordic · instalador autocontenido ══"
echo

# ── 1. VALIDACIONES previas ────────────────────────────────────────────────
step "validando entorno…"
[ "$(id -u)" -ne 0 ] || die "ejecútalo con tu usuario normal (ej: kali), no como root."
command -v sudo >/dev/null 2>&1 || die "sudo no está disponible."
sudo -n true 2>/dev/null || die "sudo sin contraseña cacheada: ejecuta 'sudo -v' antes y relanza."
if [ -r /etc/os-release ] && grep -qiE 'kali|debian' /etc/os-release; then
    step "  ✓ sistema: $(. /etc/os-release 2>/dev/null; echo "${PRETTY_NAME:-kali}")"
else
    FAIL+=("no detecto Kali/Debian (revisa /etc/os-release)")
fi
FREE_GB=$(df -BG --output=avail "$HOME" 2>/dev/null | tail -1 | tr -dc '0-9')
[ "${FREE_GB:-0}" -ge 2 ] 2>/dev/null || FAIL+=("menos de 2 GB libres en $HOME")
[ "$(stat -f -c '%T' "$HOME/.cache" 2>/dev/null || echo fs)" != "unknown" ] || true
for c in tar gzip base64 md5sum; do
    command -v "$c" >/dev/null 2>&1 || FAIL+=("falta utilidad base: $c")
done
if [ "${#FAIL[@]}" -gt 0 ]; then
    printf '\n  ✘ VALIDACIONES FALLIDAS:\n'
    for f in "${FAIL[@]}"; do printf '    • %s\n' "$f"; done
    exit 1
fi
step "  ✓ validaciones de entorno OK (kali/debian, sudo, ≥2GB, utilidades)"

# ── 2. decodificación + verificación del payload embebido ───────────────────
PAYLOAD_MD5="9d6b70a234fb0de3b0d5e5a77202e877"
WORK="$HOME/.cache/nordic/install-repo.$$"
mkdir -p "$WORK"
step "descodificando el payload embebido (~3 MB)…"
awk '/^__PAYLOAD_B64__$/{f=1;next} f{print}' "$0" | base64 -d > "$WORK/payload.tar.gz"
GOT_MD5=$(md5sum "$WORK/payload.tar.gz" | cut -d' ' -f1)
[ "$GOT_MD5" = "$PAYLOAD_MD5" ] || die "MD5 del payload no coincide ($GOT_MD5 ≠ $PAYLOAD_MD5): paquete corrupto."
step "  ✓ payload íntegro (md5 $GOT_MD5)"

# ── 3. extracción ──────────────────────────────────────────────────────────
tar -xf "$WORK/payload.tar.gz" -C "$WORK"
chmod -R u+w "$WORK"

# ── 4. instalación (install.sh del repo embebido; idempotente) ───────────────
step "instalando el entorno (instala paquetes apt propios que falten)…"
bash "$WORK/install.sh"

# ── 5. POST-VALIDACIÓN ──────────────────────────────────────────────────────
step "verificando la instalación…"
MISS=0
check() { [ -e "$1" ] && step "  ✓ $1" || { step "  ✘ $1"; MISS=$((MISS+1)); }; }
check "$HOME/.config/bspwm/bspwmrc"
check "$HOME/.config/bspwm/autostart.sh"
check "$HOME/.config/sxhkd/sxhkdrc"
check "$HOME/.config/polybar/config.ini"
check "$HOME/.config/polybar/scripts/barleft.sh"
check "$HOME/.config/polybar/scripts/workspaces.sh"
check "$HOME/.config/kitty/kitty.conf"
check "$HOME/.config/rofi/config.rasi"
check "$HOME/.config/picom/picom.conf"
check "$HOME/.config/zsh/zshrc"
check "$HOME/.local/bin/settarget"
check "$HOME/.local/bin/nordic-typeip"
check "$HOME/.local/bin/nordic-lock"
check "/usr/local/bin/settarget"
check "/usr/share/xsessions/bspwm.desktop"
check "/usr/share/nordic/nordic.nanorc"
check "/etc/nanorc"
check "/etc/lightdm/lightdm.conf.d/99-nordic.conf"
check "/etc/lightdm/lightdm-gtk-greeter.conf.d/99-nordic-greeter.conf"
check "/etc/systemd/system/nordic-lock-before-sleep.service"
sudo -n test -e /var/lib/lightdm/nordic-greeter-bg.png && step "  ✓ fondo del greeter (/var/lib/lightdm/nordic-greeter-bg.png)" || { step "  ✘ fondo del greeter"; MISS=$((MISS+1)); }
# teclado español activo
grep -q 'setxkbmap es' "$HOME/.config/bspwm/bspwmrc" 2>/dev/null && step "  ✓ teclado es en bspwmrc" || { step "  ✘ teclado es"; MISS=$((MISS+1)); }
# unit de bloqueo habilitada
systemctl is-enabled nordic-lock-before-sleep.service >/dev/null 2>&1 && step "  ✓ hook de bloqueo al suspender habilitado" || { step "  ✘ hook de bloqueo al suspender"; MISS=$((MISS+1)); }
command -v zsh >/dev/null 2>&1 && [ "$(getent passwd "$(id -un)" | cut -d: -f7)" = "$(command -v zsh)" ] && step "  ✓ zsh como shell por defecto" || { step "  ✘ zsh por defecto"; MISS=$((MISS+1)); }

rm -rf "$WORK"
if [ "$MISS" -gt 0 ]; then
    printf '\n  ⚠ %d comprobaciones fallaron — revisa con nordic-doctor.\n' "$MISS"
    exit 1
fi
printf '\n  ✔ ENTORNO MONTADO COMPLETO. Cierra sesión y elige la sesión "bspwm" en el login Nord.\n'
exit 0

__PAYLOAD_B64__

